            if (!cmd.hasOption(option) && !selected) {

                // get the value from the properties

                final String value = properties.getProperty(option);



                if (opt.hasArg()) {

                    if (opt.isValuesEmpty()) {

                        opt.processValue(stripLeadingAndTrailingQuotesDefaultOff(value));

