        if (option.getOpt() != null) {

            buff.append(OptionFormatter.DEFAULT_OPT_PREFIX).append(option.getOpt());

        } else {

            buff.append(OptionFormatter.DEFAULT_LONG_OPT_PREFIX).append(option.getLongOpt());

