        }

        if (isDeprecated()) {

            buf.append(Char.SP);

            buf.append(deprecated.toString());

        }

        if (hasArgs()) {

            buf.append("[ARG...]");

        } else if (hasArg()) {

            buf.append(" [ARG]");

        }

        // @formatter:off

        return buf.append(" :: ")

            .append(description)

            .append(" :: ")

            .append(type)

            .append(" ]")

            .toString();

        // @formatter:on

