        Method method = Option.class.getDeclaredMethod("processValue", String.class);
        method.setAccessible(true);

        // Add first value
        opt.processValue("first");
        assertEquals(1, opt.getValuesList().size());

        // Add second value that has separator - should stop at limit
        method.invoke(opt, "a=b=c");

        // values.size() was 1, argCount is 2, so argCount - 1 is 1
        // When values.size() == argCount - 1 (1 == 1), it breaks before adding the next value
        final List<String> values = opt.getValuesList();
        assertEquals(2, values.size());
        assertEquals("first", values.get(0));
        // a is added, then it breaks when size becomes 1 (equal to argCount-1=1)
        // Then "b=c" is added as the remaining
        assertEquals("a", values.get(1));
    }
