        buff.append("[");

        while (iter.hasNext()) {

            final Option option = iter.next();

            if (option.getOpt() != null) {

                buff.append(OptionFormatter.DEFAULT_OPT_PREFIX);

                buff.append(option.getOpt());

            } else {

